# A test id that cannot load also exits non-zero, which reads as a kill; refuse one.
import re
assert all(re.fullmatch(r"test_\w+\.Test\w+\.test_\w+", m[4]) for m in M), \
    [m[0] for m in M if not re.fullmatch(r"test_\w+\.Test\w+\.test_\w+", m[4])]
env = dict(os.environ, PYTHONDONTWRITEBYTECODE="1")
bad = 0
for name, f, old, new, test in M:
    p = skill / f; src = p.read_text()
    assert src.count(old) == 1, f"anchor not unique/absent for {name!r}: {src.count(old)}"
    p.write_text(src.replace(old, new))
    try:
        r = subprocess.run([sys.executable, "-m", "unittest", test], cwd=skill / "tests", env=env, capture_output=True, text=True)
    finally:
        p.write_text(src)
    killed = r.returncode != 0
    bad += not killed
    print(("KILLED " if killed else "SURVIVED ") + name)
r = subprocess.run([sys.executable, "-m", "unittest", "discover", "-s", "tests"], cwd=skill, env=env, capture_output=True, text=True)
print("restored suite:", "OK" if r.returncode == 0 else "FAIL\n" + r.stderr[-800:])
sys.exit(bad)
